#!/usr/bin/env bash
# Writes the Homebrew formula for a release to stdout, from the checksums.txt that package.sh
# made; release.yml commits it to diphyx/homebrew-tap as Formula/shipo.rb.
#
#   .github/scripts/formula.sh v1.2.3 dist/checksums.txt > Formula/shipo.rb
set -euo pipefail

tag="${1:?usage: formula.sh <tag> <checksums.txt>}"
sums="${2:?usage: formula.sh <tag> <checksums.txt>}"
version="${tag#v}"

sha() {
    local file="shipo_${version}_$1.tar.gz"
    local sum
    sum="$(awk -v f="$file" '$2 == f { print $1 }' "$sums")"
    test -n "$sum" || { echo "no checksum for $file" >&2; exit 1; }
    echo "$sum"
}

darwin_arm64="$(sha darwin_arm64)"
darwin_amd64="$(sha darwin_amd64)"
linux_arm64="$(sha linux_arm64)"
linux_amd64="$(sha linux_amd64)"

cat <<EOF
# Generated by .github/scripts/formula.sh in diphyx/shipo on each release; do not edit.
class Shipo < Formula
  desc "Bump, tag, push and release in one safe, easy command"
  homepage "https://github.com/diphyx/shipo"
  version "${version}"
  license "MIT"

  on_macos do
    on_arm do
      url "https://github.com/diphyx/shipo/releases/download/${tag}/shipo_${version}_darwin_arm64.tar.gz"
      sha256 "${darwin_arm64}"
    end
    on_intel do
      url "https://github.com/diphyx/shipo/releases/download/${tag}/shipo_${version}_darwin_amd64.tar.gz"
      sha256 "${darwin_amd64}"
    end
  end

  on_linux do
    on_arm do
      url "https://github.com/diphyx/shipo/releases/download/${tag}/shipo_${version}_linux_arm64.tar.gz"
      sha256 "${linux_arm64}"
    end
    on_intel do
      url "https://github.com/diphyx/shipo/releases/download/${tag}/shipo_${version}_linux_amd64.tar.gz"
      sha256 "${linux_amd64}"
    end
  end

  def install
    bin.install "shipo"
  end

  test do
    assert_match version.to_s, shell_output("#{bin}/shipo --version")
  end
end
EOF
